const results = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  let dbItem;
  try {
    dbItem = $('Get Active Databases').all()[i].json;
  } catch (e) {
    console.error('Could not get active database item:', e.message);
  }
  const dbId = dbItem ? dbItem.database_id : (item.json.database_id || '');
  const dbName = dbItem ? dbItem.name : (item.json.name || '');
  const dbType = dbItem ? dbItem.type : (item.json.type || 'database');

  if (item.json.results && Array.isArray(item.json.results)) {
    for (const page of item.json.results) {
      results.push({
        json: {
          ...page,
          database_id: dbId,
          database_name: dbName,
          database_type: dbType
        }
      });
    }
  }
}
return results;

const results = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const blocksResponse = items[i].json;

  let pageItem;
  try {
    pageItem = $('Split Pages List').all()[i].json;
  } catch (e) {
    console.error('Could not retrieve parent page item:', e.message);
    continue;
  }

  let database_id = pageItem.database_id || '';
  if (!database_id && pageItem.parent && pageItem.parent.type === 'database_id') {
    database_id = pageItem.parent.database_id;
  }
  if (database_id) {
    database_id = database_id.replace(/-/g, '');
  }

  const database_type = pageItem.database_type || 'database';

  let title = '';
  const parsedProps = {};
  if (pageItem.properties) {
    for (const key of Object.keys(pageItem.properties)) {
      const prop = pageItem.properties[key];
      if (!prop) continue;
      const type = prop.type;
      let val = null;
      if (type === 'title') {
        if (prop.title && prop.title.length > 0) {
          val = prop.title.map(t => t.plain_text).join('');
          title = val;
        }
      } else if (type === 'rich_text') {
        val = prop.rich_text ? prop.rich_text.map(t => t.plain_text).join('') : '';
      } else if (type === 'number') {
        val = prop.number;
      } else if (type === 'select') {
        val = prop.select ? prop.select.name : null;
      } else if (type === 'multi_select') {
        val = prop.multi_select ? prop.multi_select.map(s => s.name).join(', ') : '';
      } else if (type === 'date') {
        val = prop.date ? prop.date.start : null;
      } else if (type === 'checkbox') {
        val = prop.checkbox;
      } else if (type === 'url') {
        val = prop.url;
      } else if (type === 'email') {
        val = prop.email;
      } else if (type === 'phone_number') {
        val = prop.phone_number;
      } else if (type === 'people') {
        val = prop.people ? prop.people.map(p => p.name || p.id).join(', ') : '';
      }
      parsedProps[key] = val;
    }
  }
  if (!title) {
    title = pageItem.title || pageItem.name || 'Untitled';
  }

  let icon = '';
  if (pageItem.icon) {
    icon = pageItem.icon.emoji || (pageItem.icon.external ? pageItem.icon.external.url : (pageItem.icon.file ? pageItem.icon.file.url : ''));
  }

  let cover_url = '';
  if (pageItem.cover) {
    cover_url = pageItem.cover.external ? pageItem.cover.external.url : (pageItem.cover.file ? pageItem.cover.file.url : '');
  }

  const url = pageItem.url || '';
  const created_time = pageItem.created_time || pageItem.createdTime || new Date().toISOString();
  const last_edited_time = pageItem.last_edited_time || pageItem.lastEditedTime || new Date().toISOString();

  let textContent = '';
  const toDos = [];

  if (blocksResponse && blocksResponse.results) {
    for (const block of blocksResponse.results) {
      const btype = block.type;
      const bcontent = block[btype];
      if (!bcontent) continue;

      let btext = '';
      if (bcontent.rich_text) {
        btext = bcontent.rich_text.map(t => t.plain_text).join('');
      } else if (btype === 'child_page') {
        btext = `[Subpage: ${bcontent.title || ''}]`;
      } else if (btype === 'child_database') {
        btext = `[Database: ${bcontent.title || ''}]`;
      }

      if (btype === 'to_do') {
        const checkedStr = bcontent.checked ? '[x]' : '[ ]';
        const todoLine = `${checkedStr} ${btext}`;
        toDos.push(todoLine);
        textContent += todoLine + '\n';
      } else if (btype === 'code') {
        textContent += `\`\`\`${bcontent.language || ''}
${btext}
\`\`\`
`;
      } else if (btext) {
        if (btype.startsWith('heading_')) {
          textContent += `
### ${btext}
`;
        } else if (btype === 'bulleted_list_item') {
          textContent += `* ${btext}
`;
        } else if (btype === 'numbered_list_item') {
          textContent += `1. ${btext}
`;
        } else if (btype === 'quote') {
          textContent += `> ${btext}
`;
        } else if (btype === 'callout') {
          textContent += `💡 ${btext}
`;
        } else {
          textContent += btext + '
';
        }
      }
    }
  }
  if (!textContent.trim()) {
    textContent = JSON.stringify(parsedProps);
  }

  let meeting_date = null;
  let attendees = '';
  let summary = '';
  let transcription = '';
  let action_items = '';
  let recording_url = '';

  for (const k of Object.keys(parsedProps)) {
    const lk = k.toLowerCase();
    const val = parsedProps[k];
    if (!val) continue;
    if (lk.includes('date') && !meeting_date) {
      meeting_date = val;
    } else if ((lk.includes('attendee') || lk.includes('participant') || lk.includes('who') || lk.includes('people')) && !attendees) {
      attendees = String(val);
    } else if ((lk.includes('summary') || lk.includes('tldr') || lk.includes('overview')) && !summary) {
      summary = String(val);
    } else if ((lk.includes('transcript') || lk.includes('transcription')) && !transcription) {
      transcription = String(val);
    } else if ((lk.includes('action') || lk.includes('next step') || lk.includes('task')) && !action_items) {
      action_items = String(val);
    } else if ((lk.includes('recording') || lk.includes('video') || lk.includes('audio') || lk.includes('link')) && !recording_url) {
      recording_url = String(val);
    }
  }

  if (!meeting_date) {
    meeting_date = created_time;
  }
  if (!transcription) {
    transcription = textContent;
  }
  if (!summary) {
    summary = textContent.slice(0, 500);
  }
  if (!action_items && toDos.length > 0) {
    action_items = toDos.join('
');
  }

  const isMeetingNotes = database_type === 'meeting_notes';

  results.push({
    json: {
      id: pageItem.id,
      database_id,
      database_type,
      entity_type: isMeetingNotes ? 'meeting_notes' : 'page',
      title,
      content: textContent,
      properties: parsedProps,
      icon,
      cover_url,
      url,
      created_time,
      last_edited_time,
      meeting_date,
      attendees,
      summary,
      transcription,
      action_items,
      recording_url
    }
  });
}
return results;

const pages = [];
const meetingNotes = [];

for (const item of $input.all()) {
  if (item.json.entity_type === 'meeting_notes') {
    meetingNotes.push(item);
  } else {
    pages.push(item);
  }
}

return [pages, meetingNotes];
